import{_ as r,c as t,o,b0 as i}from"./chunks/framework.BpbtKNwe.js";const a="/aillm-docs/assets/image-20251104233920049.Cw-0KVgH.png",l="/aillm-docs/assets/v2-7464aa02168f9969a5c1aab1d389ec21_1440w.DBBZN4Uy.jpg",n="/aillm-docs/assets/image-20251105000752402.DzmauEsj.jpg",d="/aillm-docs/assets/image-20251105001052314.CDBNn0yu.jpg",s="/aillm-docs/assets/image-20251105002333469.DYleJCg8.png",g=JSON.parse('{"title":"LV001-显卡简介","description":null,"frontmatter":{"title":"LV001-显卡简介","date":"2025-11-10T21:59:20.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/cuda/cuda-basic/126b143b10f028275eb172fd","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-10T21:59:20.642Z","fulluuid":"75eb172fd2644566802b9d85fec311f4","useduuid":"75eb172fd"}},"headers":[],"relativePath":"sdoc/cuda/cuda-basic/126b143b10f028275eb172fd.md","filePath":"sdoc/10-CUDA编程/05-CUDA基础/LV001-显卡简介.md","lastUpdated":1767430713000}'),c={name:"sdoc/cuda/cuda-basic/126b143b10f028275eb172fd.md"};function h(p,e,m,u,b,f){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="lv001-显卡简介" tabindex="-1">LV001-显卡简介 <a class="header-anchor" href="#lv001-显卡简介" aria-label="Permalink to &quot;LV001-显卡简介&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>当年买了联想的 R9000P，带了一块名为 <code>NVIDIA GeForce RTX 3060 Laptop GPU</code> 的显卡：</p><table><tbody><tr><td> 品牌 </td><td> NVIDIA </td></tr><tr><td> 显存大小 </td><td> 6 GB </td></tr><tr><td> 显卡名称 </td><td> NVIDIA GeForce RTX 3060 Laptop GPU </td></tr><tr><td> 驱动日期 </td><td> 2023-11-30 </td></tr><tr><td> 驱动版本 </td><td> 31.0.15.4630 </td></tr><tr><td> 名称 </td><td> NVIDIA GeForce RTX 3060 Laptop GPU </td></tr></tbody></table><p>当然，到这篇笔记的时候，已经出到了 GeForce RTX 50 系列的显卡。但是我自己是没怎么玩过游戏，所以显卡的作用其实并不明显，直到开始跑大模型。</p><blockquote><p><a href="https://www.nvidia.cn/geforce/graphics-cards/30-series/rtx-3060-3060ti/" target="_blank" rel="noreferrer">GeForce RTX 3060 系列提供 3060 显卡和 3060 Ti 显卡 | NVIDIA</a></p></blockquote><h2 id="二、显卡简介" tabindex="-1">二、显卡简介 <a class="header-anchor" href="#二、显卡简介" aria-label="Permalink to &quot;二、显卡简介&quot;">​</a></h2><h3 id="_1-什么是显卡" tabindex="-1">1. 什么是显卡 <a class="header-anchor" href="#_1-什么是显卡" aria-label="Permalink to &quot;1. 什么是显卡&quot;">​</a></h3><p>真要是概念的话，还是直接看百科吧：</p><p><strong>显卡</strong>（<strong>Video card</strong>、<strong>Display card</strong>、<strong>Graphics card</strong>、<strong>Video adapter</strong>），全称显示接口卡，又称显示适配器。是个人 <a href="https://baike.baidu.com/item/%E8%AE%A1%E7%AE%97%E6%9C%BA/140338?fromModule=lemma_inlink" target="_blank" rel="noreferrer">计算机</a> <a href="https://baike.baidu.com/item/%E5%9F%BA%E7%A1%80/5578582?fromModule=lemma_inlink" target="_blank" rel="noreferrer">基础</a> 的组成部分之一，将 <a href="https://baike.baidu.com/item/%E8%AE%A1%E7%AE%97%E6%9C%BA%E7%B3%BB%E7%BB%9F/7210959?fromModule=lemma_inlink" target="_blank" rel="noreferrer">计算机系统</a> 需要的 <a href="https://baike.baidu.com/item/%E6%98%BE%E7%A4%BA/9985945?fromModule=lemma_inlink" target="_blank" rel="noreferrer">显示</a> 信息进行 <a href="https://baike.baidu.com/item/%E8%BD%AC%E6%8D%A2/197560?fromModule=lemma_inlink" target="_blank" rel="noreferrer">转换</a> <a href="https://baike.baidu.com/item/%E9%A9%B1%E5%8A%A8/2765136?fromModule=lemma_inlink" target="_blank" rel="noreferrer">驱动</a> <a href="https://baike.baidu.com/item/%E6%98%BE%E7%A4%BA%E5%99%A8/362722?fromModule=lemma_inlink" target="_blank" rel="noreferrer">显示器</a>，并向显示器提供逐行或 <a href="https://baike.baidu.com/item/%E9%9A%94%E8%A1%8C%E6%89%AB%E6%8F%8F/2081106?fromModule=lemma_inlink" target="_blank" rel="noreferrer">隔行扫描</a> 信号，控制 <a href="https://baike.baidu.com/item/%E6%98%BE%E7%A4%BA%E5%99%A8/362722?fromModule=lemma_inlink" target="_blank" rel="noreferrer">显示器</a> 的正确显示，是连接 <a href="https://baike.baidu.com/item/%E6%98%BE%E7%A4%BA%E5%99%A8/362722?fromModule=lemma_inlink" target="_blank" rel="noreferrer">显示器</a> 和 <a href="https://baike.baidu.com/item/%E4%B8%AA%E4%BA%BA%E8%AE%A1%E7%AE%97%E6%9C%BA/3731770?fromModule=lemma_inlink" target="_blank" rel="noreferrer">个人计算机</a> <a href="https://baike.baidu.com/item/%E4%B8%BB%E6%9D%BF/104636?fromModule=lemma_inlink" target="_blank" rel="noreferrer">主板</a> 的重要组件，是“人机”的 <a href="https://baike.baidu.com/item/%E9%87%8D%E8%A6%81%E8%AE%BE%E5%A4%87/417127?fromModule=lemma_inlink" target="_blank" rel="noreferrer">重要设备</a> 之一，其内置的 <a href="https://baike.baidu.com/item/%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97/113443?fromModule=lemma_inlink" target="_blank" rel="noreferrer">并行计算</a> 能力现阶段也用于 <a href="https://baike.baidu.com/item/%E6%B7%B1%E5%BA%A6%E5%AD%A6%E4%B9%A0/3729729?fromModule=lemma_inlink" target="_blank" rel="noreferrer">深度学习</a> 等运算。</p><p>显卡业的竞争也是日趋激烈。各类品牌名目繁多，像华硕、影驰、蓝宝石等。但是需要注意，他们其实是最终成品的板卡厂商，显卡核心芯片 GPU 主要是英伟达、AMD、英特尔等。当然还有一些其他家的。</p><blockquote><p>什么是 N 卡 A 卡，公版卡、非公版卡?</p><ul><li><strong>A 卡：</strong> 采用 AMD 芯片的显卡，统称为 A 卡。</li><li><strong>N 卡：</strong> 采用 NVIDIA 芯片的显卡，统称为 N 卡。</li><li><strong>公版显卡：</strong> 显卡芯片厂商 英伟达或 AMD 发布的，经过稳定测验的第一代显卡。</li><li><strong>非公版显卡：</strong> 其他厂商通过购买 英伟达、AMD 的芯片，来改造外观、散热等设计方案再发布出来的显卡。例如：华硕、微星、技嘉、索泰等。</li></ul></blockquote><h3 id="_2-显卡的种类" tabindex="-1">2. 显卡的种类 <a class="header-anchor" href="#_2-显卡的种类" aria-label="Permalink to &quot;2. 显卡的种类&quot;">​</a></h3><h4 id="_2-1-集成显卡" tabindex="-1">2.1 集成显卡 <a class="header-anchor" href="#_2-1-集成显卡" aria-label="Permalink to &quot;2.1 集成显卡&quot;">​</a></h4><p>集成显卡是将显示芯片、显存及其相关电路都做在主板上，与主板融为一体；集成显卡的显示芯片有单独的，但大部分都集成在主板的北桥芯片中；一些主板集成的显卡也在主板上单独安装了显存，但其容量较小，集成显卡的显示效果与处理性能相对较弱，不能对显卡进行硬件升级，但可以通过 CMOS 调节频率或刷入新 BIOS 文件实现软件升级来挖掘显示芯片的潜能。</p><p>集成显卡的优点：是功耗低、发热量小、部分集成显卡的性能已经可以媲美入门级的独立显卡，所以不用花费额外的资金购买显卡。</p><p>集成显卡的缺点：性能相对略低，且固化在主板或 CPU 上，本身无法更换，如需更换，只能与主板或显卡一次性更换。</p><h4 id="_2-2-独立显卡" tabindex="-1">2.2 独立显卡 <a class="header-anchor" href="#_2-2-独立显卡" aria-label="Permalink to &quot;2.2 独立显卡&quot;">​</a></h4><p>也就是我们平时说的独显独立显卡是指将显示芯片、显存及其相关电路单独做在一块电路板上，自成一体而作为一块独立的板卡存在，它需占用主板的扩展插槽（ISA、PCI、AGP 或 PCI-E）。</p><p>独立显卡的优点：单独安装有显存，一般不占用系统内存，在技术上也较集成显卡先进得多，比集成显卡能够得到更好的显示效果和性能，容易进行显卡的硬件升级。</p><p>独立显卡的缺点：系统功耗有所加大，发热量也较大，需额外花费购买显卡的资金，同时（特别是对手提电脑）占用更多空间。</p><h4 id="_2-3-核芯显卡" tabindex="-1">2.3 核芯显卡 <a class="header-anchor" href="#_2-3-核芯显卡" aria-label="Permalink to &quot;2.3 核芯显卡&quot;">​</a></h4><p>核芯显卡和以往的显卡设计不同，Intel 和 AMD 凭借其在处理器制程上的先进工艺以及新的架构设计，将图形核心与处理核心整合在同一块基板上，构成一颗完整的处理器。</p><p>智能处理器架构这种设计上的整合大大缩减了处理核心、图形核心、内存及内存控制器间的数据周转时间，有效提升处理效能并大幅降低芯片组整体功耗，有助于缩小了核心组件的尺寸，为手提电脑、一体机等产品的设计提供了更大选择空间。</p><p>核芯显卡的优点：低功耗是核芯显卡的最主要优势，由于新的精简架构及整合设计，核芯显卡对整体能耗的控制更加优异，高效的处理性能大幅缩短了运算时间，进一步缩减了系统平台的能耗。</p><p>核芯显卡的缺点：配置核芯显卡的 CPU 通常价格较高，同时其难以胜任大型游戏。</p><h3 id="_4-显卡的组成" tabindex="-1">4. 显卡的组成 <a class="header-anchor" href="#_4-显卡的组成" aria-label="Permalink to &quot;4. 显卡的组成&quot;">​</a></h3><p>平时我们网上买显卡的话，一搜，大概是这样的，外形都是几个散热扇，这个就是显卡的散热了。</p><img src="'+a+'" alt="image-20251104233920049" style="zoom:45%;"><p>显卡(Video card，Graphics card)全称显示接口卡，又称显示适配器。由显卡核心（GPU） 、电路板（PCB）、显存、金手指、供电 &amp; 显示接口以及散热等构成：</p><img src="'+l+'" alt="img" style="zoom:25%;"><p>下面介绍几个重要部分。</p><h4 id="_4-1-图形处理单元-gpu" tabindex="-1">4.1 图形处理单元 GPU <a class="header-anchor" href="#_4-1-图形处理单元-gpu" aria-label="Permalink to &quot;4.1 图形处理单元 GPU&quot;">​</a></h4><p>GPU 是显卡的核心部件，负责处理图形数据及执行复杂的图形计算任务。它是显卡性能的关键决定因素，能够并行处理大量数据，特别适用于图形渲染、3D 建模及视频解码等。</p><img src="'+n+'" alt="image-20251105000752402" style="zoom:25%;"><h4 id="_4-2-显存-vram" tabindex="-1">4.2 显存 (VRAM) <a class="header-anchor" href="#_4-2-显存-vram" aria-label="Permalink to &quot;4.2 显存 (VRAM)&quot;">​</a></h4><p>显存是专为 GPU 服务的高速内存，用于存储图形处理过程中的临时数据，例如纹理、帧缓冲和顶点信息。显存的容量和带宽直接影响显卡处理高分辨率图像和复杂视觉效果的能力。</p><img src="'+d+'" style="zoom:33%;"><h4 id="_4-3-散热系统" tabindex="-1">4.3 散热系统 <a class="header-anchor" href="#_4-3-散热系统" aria-label="Permalink to &quot;4.3 散热系统&quot;">​</a></h4><p>散热系统对于高性能显卡至关重要，它包括散热片、热管、风扇乃至液冷装置，确保 GPU 在高负荷运行时能维持适宜的工作温度，避免过热导致性能下降或硬件损坏。</p><img src="'+a+'" alt="image-20251104233920049" style="zoom:45%;"><h3 id="_5-nvidia" tabindex="-1">5. NVIDIA <a class="header-anchor" href="#_5-nvidia" aria-label="Permalink to &quot;5. NVIDIA&quot;">​</a></h3><h4 id="_5-1-nvidia-简介" tabindex="-1">5.1 NVIDIA 简介 <a class="header-anchor" href="#_5-1-nvidia-简介" aria-label="Permalink to &quot;5.1 NVIDIA 简介&quot;">​</a></h4><p>因为我的显卡是 NVIDIA 的，这里就简单了解下 NVIDIA 吧。</p><p>NVIDIA（NVIDIA Corporation，NASDAQ：NVDA，发音：发音： /ɪnˈvɪdiə/[3]，台湾与香港地区官方中文名为辉达，中国大陆翻译成英伟达），创立于 1993 年 1 月，是一家以设计和销售图形处理器为主的 <strong>无厂半导体公司</strong>。</p><p>理解能力没偏差的话，应该注意到了，NV 是一家“无厂半导体公司”，类似归纳为这样的公司，还包括高通、博通、联发科、AMD、苹果等。</p><p>它们共同的特点主要是，它们只负责设计芯片，但落实到生产环节，就必须要依赖类似台积电、GF（从 AMD 分离出去）、三星等第三方半导体生产厂商生产。例如苹果的芯片，是由三星生产的（也有一部分台积电）。</p><h4 id="_5-2-命名规则" tabindex="-1">5.2 命名规则 <a class="header-anchor" href="#_5-2-命名规则" aria-label="Permalink to &quot;5.2 命名规则&quot;">​</a></h4><p>简单了解一下英伟达显卡的命名规则。</p><h5 id="_5-2-1-前缀" tabindex="-1">5.2.1 前缀 <a class="header-anchor" href="#_5-2-1-前缀" aria-label="Permalink to &quot;5.2.1 前缀&quot;">​</a></h5><ul><li><strong>无前缀：</strong> 通常表示低端或入门级的显卡，适合日常使用和轻度视频观看，如 GeForce 210 等。</li><li><strong>GT：</strong> 表示中低端的显卡，适合高清视频观看、3D 电影和入门级游戏，如 GeForce GT 1030、GeForce GT 730 等。</li><li><strong>GTX：</strong> 表示中高端的显卡，适合游戏和图形设计，如 GeForce GTX 1660、GeForce GTX 1050 Ti 等。</li><li><strong>RTX：</strong> 表示高端或旗舰级的显卡，适合高性能游戏和图形设计，支持光线追踪技术，如 GeForce RTX 3080、GeForce RTX 4090 等。</li></ul><h5 id="_5-2-2-代数-显卡的世代和架构" tabindex="-1">5.2.2 代数：显卡的世代和架构 <a class="header-anchor" href="#_5-2-2-代数-显卡的世代和架构" aria-label="Permalink to &quot;5.2.2 代数：显卡的世代和架构&quot;">​</a></h5><p>代数代表了显卡的世代和对应的 GPU 架构。例如，30 代对应 Ampere 架构，20 代对应 Turing 架构，10 代对应 Pascal 架构等。代数越大，通常表示显卡越新，性能越强，功能也越多。</p><h5 id="_5-2-3-等级-显卡的性能级别" tabindex="-1">5.2.3 等级：显卡的性能级别 <a class="header-anchor" href="#_5-2-3-等级-显卡的性能级别" aria-label="Permalink to &quot;5.2.3 等级：显卡的性能级别&quot;">​</a></h5><p>等级一般由两位或三位数字组成，如 60、70、80、90、1650、2060 等。等级越高，表示显卡的性能越强，价格也越贵。例如，在同一系列中，GeForce RTX 3080 的性能明显优于 GeForce RTX 3060。</p><h5 id="_5-2-4-版本-显卡的变种和优化" tabindex="-1">5.2.4 版本：显卡的变种和优化 <a class="header-anchor" href="#_5-2-4-版本-显卡的变种和优化" aria-label="Permalink to &quot;5.2.4 版本：显卡的变种和优化&quot;">​</a></h5><p>版本通常由一些字母或符号组成，如 Ti、Super、Ultra 等。版本越高，表示显卡在原有基础上进行了更多的优化和增强，性能也更强。例如，GeForce RTX 3080 Ti 就是 RTX 3080 的增强版，性能更为出色。</p><h5 id="_5-2-5-后缀-提供额外信息" tabindex="-1">5.2.5 后缀：提供额外信息 <a class="header-anchor" href="#_5-2-5-后缀-提供额外信息" aria-label="Permalink to &quot;5.2.5 后缀：提供额外信息&quot;">​</a></h5><p>除了上述规则外，NVIDIA 显卡有时还会通过后缀来提供额外的信息。例如，“Ti”后缀通常表示同等级别的增强版，而“SE”、“LE”等后缀则可能表示简化版或低功耗版。</p><h4 id="_5-3-显卡架构" tabindex="-1">5.3 显卡架构 <a class="header-anchor" href="#_5-3-显卡架构" aria-label="Permalink to &quot;5.3 显卡架构&quot;">​</a></h4><p>在 NVIDIA 官网对应产品页面或通过搜索 &quot;<strong>NVIDIA [架构名] architecture whitepaper</strong>&quot; 可以找到某个架构 GPU 的白皮书，白皮书中会介绍 CPU 架构。</p><p>从英伟达官网可以查到对应显卡是什么架构，例如 <a href="https://www.nvidia.cn/geforce/graphics-cards/30-series/rtx-3060-3060ti/" target="_blank" rel="noreferrer">GeForce RTX 3060 系列提供 3060 显卡和 3060 Ti 显卡 | NVIDIA</a>：</p><img src="'+s+'" alt="image-20251105002333469" style="zoom:50%;"><p>可以看到 RTX3060 用的是 Ampere 架构，对应的架构白皮书可以在这里找到：<a href="https://www.nvidia.com/en-us/geforce/news/rtx-30-series-ampere-architecture-whitepaper-download/" target="_blank" rel="noreferrer">NVIDIA Ampere Architecture Whitepaper Available Now | GeForce News | NVIDIA</a>，这里有这么一段：</p><blockquote><p>Our new <a href="https://www.nvidia.com/en-us/geforce/news/introducing-rtx-30-series-graphics-cards/" target="_blank" rel="noreferrer">GeForce RTX 30 Series graphics cards</a> are powered by NVIDIA Ampere architecture GA10x GPUs, which bring record breaking performance to PC gamers worldwide.</p><p>All the enhancements and features supported by our new GPUs are detailed in full <a href="https://www.nvidia.com/en-us/geforce/tags/?tag=geforce-rtx-gpus" target="_blank" rel="noreferrer">on our website</a>, but if you want an 11,000 word deep dive into all the architectural nitty gritty of our latest graphics cards, you should download the <a href="https://www.nvidia.com/content/PDF/nvidia-ampere-ga-102-gpu-architecture-whitepaper-v2.1.pdf" target="_blank" rel="noreferrer">NVIDIA Ampere GA102 GPU Architecture whitepaper</a>.</p></blockquote><p>就是新GPU支持的所有增强功能和功能都在网站上详细介绍，但如果想要深入了解我们最新显卡的所有架构细节，应该下载 <a href="https://www.nvidia.com/content/PDF/nvidia-ampere-ga-102-gpu-architecture-whitepaper-v2.1.pdf" target="_blank" rel="noreferrer">NVIDIA Ampere GA102 GPU Architecture whitepaper</a>。</p><blockquote><p>参考资料</p><p><a href="https://api.xiaoheihe.cn/maxnews/app/share/detail/1121255" target="_blank" rel="noreferrer">硬件基础科普之显卡组成</a></p><p><a href="https://cloud.tencent.com/developer/article/2442495" target="_blank" rel="noreferrer">硬件知识：一文带大家了解显卡的组成和种类-腾讯云开发者社区-腾讯云</a></p><p><a href="https://zhuanlan.zhihu.com/p/156083352" target="_blank" rel="noreferrer">(9 封私信) 【显卡科普】小白必看的入门显卡科普，关于显卡的原理、结构、作用 - 知乎</a></p></blockquote>',67)])])}const A=r(c,[["render",h]]);export{g as __pageData,A as default};
